use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioDocumentSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let text=f["text"].as_str().unwrap();SemioDocumentSnapshot{schema:f["schema"].as_str().unwrap().into(),styles:vec![DocStyle{id:"".into(),name:"root".into(),based_on:None},DocStyle{id:"child".into(),name:"child".into(),based_on:Some("".into())}],images:vec![DocImage{id:f["imageId"].as_str().unwrap().into(),mime:f["mime"].as_str().unwrap().into(),bytes:vec![0,255,127]}],blocks:vec![DocBlock::Paragraph{style_id:Some("".into()),runs:vec![DocRun{text:text.into(),style:RunStyle{bold:true,italic:true,underline:true,size:Some(-1.5),font:Some("".into()),color:Some("#ff0000".into()),link:Some("https://example.test".into())}},DocRun::plain("")]},DocBlock::Heading{level:255,style_id:Some("child".into()),runs:vec![]},DocBlock::List{ordered:true,items:vec![DocListItem{blocks:vec![DocBlock::PageBreak]},DocListItem{blocks:vec![]}]},DocBlock::Table{rows:vec![DocTableRow{cells:vec![DocTableCell{blocks:vec![DocBlock::paragraph("cell")]},DocTableCell{blocks:vec![]}]}]},DocBlock::Code{language:Some("".into()),text:text.into()},DocBlock::Quote{blocks:vec![DocBlock::Quote{blocks:vec![]}]},DocBlock::Image{image_id:f["imageId"].as_str().unwrap().into(),alt:"".into(),width:Some(0.0),height:None},DocBlock::PageBreak]}}
fn project(s:&SemioDocumentSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioDocumentSnapshot, semio_framework_value::ValueError>{SemioDocumentSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_document_all_typed_blocks_run_option_presence_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioDocumentSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioDocumentSnapshot as store::ArtifactDsl>::print_dsl(&s));assert_eq!(restore(&project(&SemioDocumentSnapshot::default())).unwrap(),SemioDocumentSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_document_rejects_cycles_ownership_variant_shapes_and_budgets(){let original=project(&fixture());for mutation in 0..6{let mut db=original.clone();match mutation{0=>db.table_mut("semio_document_style").unwrap().rows[0].values[5]=SqliteValue::Integer(2),1=>db.table_mut("semio_document_quote").unwrap().rows[0].values[1]=SqliteValue::Integer(1),2=>db.table_mut("semio_document_member").unwrap().rows[0].values[3]=SqliteValue::Integer(999),3=>db.table_mut("semio_document_heading").unwrap().rows[0].values[1]=SqliteValue::Integer(256),4=>db.table_mut("semio_document_run").unwrap().rows[0].values[4]=SqliteValue::Integer(2),_=>{db.table_mut("semio_document_image_block").unwrap().rows[0].values[1]=SqliteValue::Integer(999);}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_value_bytes:1,max_rows:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioDocumentSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_document_independent_sqlite_style_image_run_queries_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT bold,italic,underline,font FROM semio_document_run ORDER BY id').get();if(r.bold!==1||r.italic!==1||r.underline!==1||r.font!=='')throw Error('run fields');const i=db.query('SELECT native_id,length(bytes) AS size FROM semio_document_image JOIN semio_document_image_block ON image_id=semio_document_image.id').get();if(i.size!==3)throw Error('image FK');db.query(\"UPDATE semio_document_run SET text='independently edited' WHERE id=1\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let DocBlock::Paragraph{runs,..}=&mut expected.blocks[0]{runs[0].text="independently edited".into();}assert_eq!(r,expected);}

#[test]
fn sqlite_snapshot_semio_document_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioDocumentSnapshot,crate::standards::v1::subsets::document::schema::mutations::SemioDocumentMutation>("s.stdio.semio.document");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioDocumentSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"document".into()};let db=(provider.export)("s.stdio.semio.document",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.document",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_document_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();if let DocBlock::Paragraph{runs,..}=&mut s.blocks[0]{runs[0].style.size=Some(v);}let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((match &r.blocks[0]{DocBlock::Paragraph{runs,..}=>runs[0].style.size.unwrap(),_=>panic!("paragraph")}).to_bits(),bits);assert_eq!(<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_document_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_document_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_document_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"document".into()};
    let provider=<SemioDocumentSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioDocumentSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioDocumentSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_document_native_text_preserves_ieee_words(){use store::ArtifactDsl;let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let value=SemioDocumentSnapshot{blocks:vec![DocBlock::Paragraph{style_id:None,runs:vec![DocRun{text:"".into(),style:RunStyle{size:Some(f64::from_bits(bits)),..RunStyle::default()}}]}],..SemioDocumentSnapshot::default()};let actual=SemioDocumentSnapshot::parse_dsl(&value.print_dsl()).unwrap();if let DocBlock::Paragraph{runs,..}=&actual.blocks[0]{assert_eq!(runs[0].style.size.unwrap().to_bits(),bits)}else{panic!("paragraph")}}}
#[test]
fn sqlite_snapshot_semio_document_explicit_controlled_native_owner(){use store::{ArtifactPack,ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let expected=fixture();for payload in [store::os_io::IoPayload::Binary(expected.encode_pack()),store::os_io::IoPayload::Text(expected.print_dsl())]{let actual=SemioDocumentSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual,expected);assert!(SemioDocumentSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(SemioDocumentSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioDocumentSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioDocumentSnapshot{blocks:(0..count).map(|_|DocBlock::Code{language:Some("".into()),text:"".into()}).collect(),..SemioDocumentSnapshot::default()};for payload in [store::os_io::IoPayload::Binary(value.encode_pack()),store::os_io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(SemioDocumentSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(interior);}let mut root=DocBlock::PageBreak;for _ in 0..f["nativeAdmission"]["maximumDepth"].as_u64().unwrap()+1{root=DocBlock::Quote{blocks:vec![root]};}let deep=SemioDocumentSnapshot{blocks:vec![root],..SemioDocumentSnapshot::default()};assert!(SemioDocumentSnapshot::decode_sqlite_snapshot_native(&store::os_io::IoPayload::Binary(deep.encode_pack()),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

#[test]
fn sqlite_snapshot_semio_document_native_text_preserves_image_ieee_words(){
 use store::ArtifactDsl;let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut snapshot=fixture();snapshot.blocks=vec![DocBlock::Image{image_id:snapshot.images[0].id.clone(),alt:String::new(),width:Some(f64::from_bits(bits)),height:Some(f64::from_bits(bits))}];let actual=SemioDocumentSnapshot::parse_dsl(&snapshot.print_dsl()).unwrap();let DocBlock::Image{width,height,..}=&actual.blocks[0]else{panic!("image kind")};assert_eq!(width.unwrap().to_bits(),bits);assert_eq!(height.unwrap().to_bits(),bits);}
}

