#[test]
fn sqlite_snapshot_semio_document_late_reconstruction_cancellation_retires_owned_tree(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let limits=&corpus["reconstructionRetirement"];let depth=limits["depth"].as_u64().unwrap() as usize;let stack=limits["stackBytes"].as_u64().unwrap() as usize;let bytes=limits["schemaBytes"].as_u64().unwrap() as usize;let mut snapshot=fixture();snapshot.schema="x".repeat(bytes);let mut block=DocBlock::PageBreak;for _ in 0..depth{block=DocBlock::Quote{blocks:vec![block]};}snapshot.blocks=vec![block];crate::standards::v1::subsets::base::schema::snapshot::native_output_tests::assert_reconstruction(snapshot,bytes,stack);}
